<!--
  Input komentar dengan mention @user — MENIRU PERSIS perilaku desk Frappe
  (Quill + modul quill-mention), tapi tanpa Quill: pakai `contenteditable`
  supaya bundle PWA tetap ringan.

  Yang ditiru dari quill-mention (apps/frappe/.../quill-mention/quill.mention.js)
  dan ControlComment desk:
    • pemicu '@' dengan isolateCharacter → hanya jalan bila '@' di awal teks
      atau didahului spasi/baris baru;
    • kata kunci hanya boleh [A-Za-z0-9_] (regex allowedChars) & maks 31 char
      (maxChars), minChars 0 → ketik '@' saja langsung memunculkan daftar;
    • sumber daftar = frappe.desk.search.get_names_for_mentions, debounce 300ms,
      user yang terlibat di dokumen didahulukan (prioritizeUsers);
    • navigasi ↑/↓, pilih Enter/Tab/klik, tutup Esc; setelah dipilih disisipkan
      chip + satu spasi dan kursor pindah ke belakang spasi;
    • MARKUP CHIP SAMA PERSIS dengan yang disimpan desk:
      <span class="mention" data-id data-value data-denotation-char data-is-group
            [data-link]>{ZWNBSP}<span contenteditable="false">
        <span class="ql-mention-denotation-char">@</span><a …>Nama</a>
      </span>{ZWNBSP}</span>
      → `extract_mentions` (BeautifulSoup cari .mention → data-id) di
      frappe/desk/notifications.py mengenalinya, jadi Notification Log tipe
      "Mention" otomatis terkirim tanpa kode backend tambahan.

  Nilai v-model = HTML siap kirim ke `add_comment`, dibungkus
  <div class="ql-editor read-mode"><p>…</p></div> persis seperti komentar desk.

  Props:
    modelValue     : HTML komentar (biasanya '' lalu diisi komponen ini)
    placeholder    : teks bantu saat kosong
    disabled       : nonaktifkan input
    priorityUsers  : array email user "terlibat" → ditaruh di atas daftar
  Emits:
    update:modelValue, submit (Ctrl/Cmd+Enter)
-->
<template>
	<div class="relative">
		<div
			ref="editor"
			role="textbox"
			aria-multiline="true"
			:contenteditable="disabled ? 'false' : 'true'"
			:class="[
				'max-h-48 min-h-[76px] w-full overflow-y-auto whitespace-pre-wrap break-words rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30',
				disabled ? 'cursor-not-allowed bg-ui-surface-gray-50 text-ui-ink-gray-400' : '',
			]"
			@beforeinput="onBeforeInput"
			@input="onInput"
			@keydown="onKeydown"
			@keyup="detect"
			@mouseup="detect"
			@blur="onBlur"
			@paste="onPaste"
		/>

		<!-- Placeholder: `:empty` tidak dipakai karena contenteditable kerap
		     menyisakan <br> di dalamnya → dipakai flag hasContent. -->
		<span
			v-if="!hasContent"
			class="pointer-events-none absolute left-3 top-2 select-none text-base text-ui-ink-gray-400"
		>
			{{ placeholder }}
		</span>

		<!-- Daftar mention: di-Teleport ke body + posisi fixed dari rect caret →
		     tidak ter-clip container ber-overflow (tab detail bisa di-scroll). -->
		<Teleport to="body">
			<ul
				v-if="open && items.length"
				ref="list"
				class="fixed z-[70] max-h-56 overflow-y-auto rounded-xl border border-ui-line-gray-200 bg-ui-surface p-1 shadow-xl ring-1 ring-black/5"
				:style="menuStyle"
			>
				<li
					v-for="(it, i) in items"
					:key="it.id"
					:class="[
						'flex cursor-pointer items-center gap-2 rounded-lg px-3 py-2 text-sm transition',
						i === index ? 'bg-ui-surface-gray-100 font-medium text-ui-ink-gray-900' : 'text-ui-ink-gray-700',
					]"
					@mouseenter="index = i"
					@mousedown.prevent="pick(i)"
					@touchstart.prevent="pick(i)"
				>
					<span
						class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-ui-surface-orange-100 text-[10px] font-semibold text-ui-ink-orange-700"
					>
						{{ initials(it.value) }}
					</span>
					<span class="min-w-0 flex-1 truncate">{{ it.value }}</span>
				</li>
			</ul>
		</Teleport>
	</div>
</template>

<script setup>
import { nextTick, onBeforeUnmount, ref, watch } from 'vue'

const props = defineProps({
	modelValue: { type: String, default: '' },
	placeholder: { type: String, default: '' },
	disabled: { type: Boolean, default: false },
	priorityUsers: { type: Array, default: () => [] },
})
const emit = defineEmits(['update:modelValue', 'submit'])

// Konstanta disalin dari opsi quill-mention di desk (text_editor.js
// get_mention_options + default kelas Mention) supaya perilakunya identik.
const ALLOWED_CHARS = /^[A-Za-z0-9_]*$/
const MAX_CHARS = 31
const MIN_CHARS = 0
const DEBOUNCE_MS = 300

const editor = ref(null)
const list = ref(null)
const open = ref(false)
const items = ref([])
const index = ref(0)
const hasContent = ref(false)
const menuStyle = ref({})

// HTML terakhir yang kita emit — pembanding supaya `watch` pada modelValue
// hanya menulis ulang DOM saat parent benar-benar mengubah nilai (mis. reset
// setelah kirim), bukan saat nilai balik dari komponen ini sendiri.
let lastEmitted = ''
// Query aktif ({ node, start, end, term }) hasil deteksi terakhir.
let query = null

function initials(nameOrEmail) {
	const base = String(nameOrEmail || '').split('@')[0]
	const parts = base.split(/[\s._-]+/).filter(Boolean)
	if (!parts.length) return '?'
	return (parts[0][0] + (parts[1]?.[0] || '')).toUpperCase()
}

// ---- Baca query '@…' di posisi caret ---------------------------------------
// Chip mention adalah elemen (contenteditable=false) sehingga selalu memutus
// text node → '@' pasti berada di text node yang sama dengan caret. Karakter
// tepat sebelum '@' (untuk aturan isolateCharacter) diambil lewat charBefore().
function queryAtCaret() {
	const root = editor.value
	const sel = window.getSelection()
	if (!root || !sel || !sel.rangeCount || !sel.isCollapsed) return null
	const range = sel.getRangeAt(0)
	const node = range.startContainer
	if (node.nodeType !== Node.TEXT_NODE || !root.contains(node)) return null

	const from = Math.max(0, range.startOffset - MAX_CHARS)
	const before = node.data.slice(from, range.startOffset)
	const at = before.lastIndexOf('@')
	if (at < 0) return null

	// isolateCharacter: '@' harus di awal input atau didahului whitespace.
	const prev = at > 0 ? before[at - 1] : charBefore(node)
	if (prev !== null && !/\s/.test(prev)) return null

	const term = before.slice(at + 1)
	if (term.length < MIN_CHARS || !ALLOWED_CHARS.test(term)) return null

	const start = range.startOffset - (before.length - at)
	return { node, start, end: range.startOffset, term }
}

// Karakter logis tepat sebelum sebuah text node. null = awal editor.
// Chip mention dianggap satu karakter non-whitespace (di Quill embed = 1 char),
// jadi "@" yang menempel di belakang chip TIDAK memicu daftar — sama seperti desk.
function charBefore(node) {
	let cur = node
	const root = editor.value
	while (cur && cur !== root) {
		const prev = cur.previousSibling
		if (prev) {
			if (prev.nodeType === Node.TEXT_NODE) {
				if (prev.data.length) return prev.data[prev.data.length - 1]
				cur = prev
				continue
			}
			if (prev.nodeType === Node.ELEMENT_NODE) {
				if (prev.tagName === 'BR') return '\n'
				// U+FFFC (object replacement) - BUKAN U+FEFF, karena U+FEFF ikut
				// cocok dengan \s di JS sehingga chip malah dianggap spasi.
				if (prev.classList.contains('mention')) return '\ufffc'
				const text = prev.textContent
				return text ? text[text.length - 1] : '\n'
			}
			cur = prev
			continue
		}
		cur = cur.parentNode
	}
	return null
}

// ---- Sumber daftar user ----------------------------------------------------
let searchTimer = null
let blurTimer = null
let searchSeq = 0

function detect() {
	if (props.disabled) return
	clearTimeout(blurTimer) // fokus kembali sebelum penutupan tertunda berjalan
	query = queryAtCaret()
	if (!query) {
		close()
		return
	}
	const term = query.term
	clearTimeout(searchTimer)
	searchTimer = setTimeout(() => search(term), DEBOUNCE_MS)
}

async function search(term) {
	const seq = ++searchSeq
	try {
		const params = new URLSearchParams({ search_term: term })
		const res = await fetch(
			`/api/method/frappe.desk.search.get_names_for_mentions?${params.toString()}`,
			{
				method: 'GET',
				credentials: 'include',
				headers: { Accept: 'application/json' },
			}
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		if (seq !== searchSeq) return // hasil balapan lama → buang
		// User saja: User Group sengaja tidak didukung di portal.
		const values = prioritize((json.message || []).filter((v) => !v.is_group))
		items.value = values
		index.value = 0
		open.value = values.length > 0 && !!queryAtCaret()
		if (open.value) {
			await nextTick()
			position()
		}
	} catch {
		close()
	}
}

// Meniru prioritize_involved_users_in_mention: user yang terlibat di dokumen
// (owner, komentator, assignee, …) naik ke atas, sisanya menyusul.
function prioritize(values) {
	const involved = props.priorityUsers || []
	if (!involved.length) return values
	return values
		.filter((v) => involved.includes(v.id))
		.concat(values.filter((v) => !involved.includes(v.id)))
}

// ---- Sisip chip ------------------------------------------------------------
function buildChip(item) {
	const span = document.createElement('span')
	span.className = 'mention'
	// Hanya untuk mode edit (chip tak bisa diketik di tengahnya); dilepas saat
	// serialize supaya HTML tersimpan sama persis dengan milik desk.
	span.setAttribute('contenteditable', 'false')
	span.dataset.id = item.id
	// Desk menyimpan data-value berisi potongan anchor (quirk quill-mention) —
	// ditiru apa adanya agar komentar dari portal & desk tidak beda bentuk.
	span.dataset.value = item.link
		? `<a href="${item.link}" target="_blank">${item.value}`
		: item.value
	span.dataset.denotationChar = '@'
	span.dataset.isGroup = 'false'
	if (item.link) span.dataset.link = item.link

	const inner = document.createElement('span')
	inner.setAttribute('contenteditable', 'false')
	const denotation = document.createElement('span')
	denotation.className = 'ql-mention-denotation-char'
	denotation.textContent = '@'
	inner.appendChild(denotation)
	if (item.link) {
		const a = document.createElement('a')
		a.href = item.link
		a.target = '_blank'
		a.textContent = item.value
		inner.appendChild(a)
	} else {
		inner.appendChild(document.createTextNode(item.value))
	}

	span.append(document.createTextNode('\ufeff'), inner, document.createTextNode('\ufeff'))
	return span
}

function pick(i) {
	const item = items.value[i]
	const q = queryAtCaret() || query
	if (!item || !q) {
		close()
		return
	}
	const range = document.createRange()
	range.setStart(q.node, q.start)
	range.setEnd(q.node, Math.min(q.end, q.node.data.length))
	range.deleteContents()

	const chip = buildChip(item)
	// NBSP: spasi biasa di ujung baris bisa "hilang" secara visual di
	// contenteditable; dikembalikan jadi spasi biasa saat serialize.
	const space = document.createTextNode('\u00a0')
	range.insertNode(space)
	range.insertNode(chip)

	const after = document.createRange()
	after.setStart(space, 1)
	after.collapse(true)
	const sel = window.getSelection()
	sel.removeAllRanges()
	sel.addRange(after)

	close()
	emitValue()
}

// ---- Hapus chip ------------------------------------------------------------
// Di WebView Android penghapusan lewat keyboard virtual (IME) TIDAK memakai
// keydown Backspace (keycode 229) dan sering tidak membuang elemen
// contenteditable=false secara utuh: pembungkus chip hilang tapi isinya
// (nama user) tertinggal, dan caret bisa nyangkut di sisa elemen itu sehingga
// input terlihat "mati". Karena itu penghapusan chip diambil alih sendiri lewat
// `beforeinput` (didukung Chromium/WebKit, termasuk WebView), dengan
// repairChips() sebagai jaring pengaman kalau preventDefault diabaikan.
const DELETE_BACKWARD = new Set([
	'deleteContentBackward',
	'deleteWordBackward',
	'deleteSoftLineBackward',
	'deleteHardLineBackward',
])
const DELETE_FORWARD = new Set([
	'deleteContentForward',
	'deleteWordForward',
	'deleteSoftLineForward',
	'deleteHardLineForward',
])

function onBeforeInput(e) {
	if (props.disabled) return
	const backward = DELETE_BACKWARD.has(e.inputType)
	if (!backward && !DELETE_FORWARD.has(e.inputType)) return
	const sel = window.getSelection()
	if (!sel || !sel.rangeCount || !sel.isCollapsed) return // seleksi rentang → biarkan default
	const chip = adjacentChip(sel.getRangeAt(0), backward)
	if (!chip) return
	e.preventDefault()
	removeChip(chip)
}

// Chip yang menempel tepat di sebelum (backward) / sesudah (forward) caret.
function adjacentChip(range, backward) {
	const root = editor.value
	const node = range.startContainer
	const offset = range.startOffset
	if (!root || !root.contains(node)) return null

	if (node.nodeType === Node.TEXT_NODE) {
		// Masih ada karakter di sisi hapus → yang dihapus huruf biasa, bukan chip.
		if (backward ? offset > 0 : offset < node.data.length) return null
		const sibling = skipEmptyText(backward ? node.previousSibling : node.nextSibling, backward)
		return isChip(sibling) ? sibling : null
	}
	const children = node.childNodes
	const sibling = skipEmptyText(backward ? children[offset - 1] : children[offset], backward)
	return isChip(sibling) ? sibling : null
}

// Penyisipan chip memecah text node dan kerap meninggalkan potongan kosong di
// antara chip dan caret; potongan itu dilewati supaya chip tetap terdeteksi.
function skipEmptyText(node, backward) {
	let cur = node
	while (cur && cur.nodeType === Node.TEXT_NODE && cur.data.length === 0) {
		cur = backward ? cur.previousSibling : cur.nextSibling
	}
	return cur
}

function isChip(node) {
	return node?.nodeType === Node.ELEMENT_NODE && node.classList?.contains('mention')
}

function removeChip(chip) {
	const parent = chip.parentNode
	const at = [...parent.childNodes].indexOf(chip)
	const prev = chip.previousSibling
	chip.remove()

	const range = document.createRange()
	if (prev && prev.nodeType === Node.TEXT_NODE) {
		range.setStart(prev, prev.data.length)
	} else {
		range.setStart(parent, Math.min(at, parent.childNodes.length))
	}
	range.collapse(true)
	const sel = window.getSelection()
	sel.removeAllRanges()
	sel.addRange(range)

	normalizeEditor()
	emitValue()
	detect()
}

// Buang sisa-sisa chip yang rusak (mis. dihapus setengah oleh IME) supaya nama
// user tidak tertinggal di layar & caret tidak terjebak di elemen non-editable.
// Mengembalikan true kalau ada yang dibersihkan.
function repairChips() {
	const root = editor.value
	if (!root) return false
	let changed = false

	// 1. Chip yang strukturnya/labelnya tidak utuh lagi → buang seluruhnya.
	//    Aturannya keras (harus sama persis dengan nama di data-value) supaya
	//    tidak pernah ada chip yang tampil terpotong tapi tetap men-tag user —
	//    yang terlihat user harus sama dengan yang dikirim ke server.
	for (const el of [...root.querySelectorAll('.mention')]) {
		const label = el.textContent
			.replace(/\ufeff/g, '')
			.replace(/^@/, '')
			.trim()
		if (
			!el.dataset.id ||
			!el.querySelector('.ql-mention-denotation-char') ||
			label !== expectedLabel(el)
		) {
			el.remove()
			changed = true
		}
	}
	// 2. Potongan chip yang kehilangan pembungkus .mention-nya.
	for (const el of [
		...root.querySelectorAll('[contenteditable], .ql-mention-denotation-char'),
	]) {
		if (!el.closest('.mention')) {
			el.remove()
			changed = true
		}
	}
	// 3. Karakter penjaga U+FEFF yang tercecer di luar chip — sisa ini yang bikin
	//    caret "menempel" di posisi mati pada sebagian WebView.
	// 4 = NodeFilter.SHOW_TEXT (dituliskan defensif: konstantanya tidak selalu
	// terekspos di semua WebView lama).
	const walker = document.createTreeWalker(root, window.NodeFilter?.SHOW_TEXT ?? 4)
	const strays = []
	while (walker.nextNode()) {
		const node = walker.currentNode
		if (node.data.includes('\ufeff') && !node.parentElement?.closest('.mention')) {
			strays.push(node)
		}
	}
	for (const node of strays) {
		const cleaned = node.data.replace(/\ufeff/g, '')
		if (cleaned) node.data = cleaned
		else node.remove()
		changed = true
	}
	return changed
}

// Nama yang seharusnya tampil di sebuah chip. data-value mengikuti quirk
// quill-mention: berisi potongan anchor ("<a href=…>Nama") kalau ada link.
function expectedLabel(el) {
	const raw = el.dataset.value || ''
	const name = raw.includes('>') ? raw.slice(raw.lastIndexOf('>') + 1) : raw
	return name.trim()
}

// Pastikan editor selalu dalam kondisi bisa diketik: tanpa sisa elemen kosong,
// dan caret berada di dalam editor (bukan di elemen non-editable / di luar).
function normalizeEditor() {
	const root = editor.value
	if (!root) return
	if (!root.querySelector('.mention') && !root.textContent.replace(/[\s\ufeff]/g, '')) {
		root.innerHTML = ''
	}
	const sel = window.getSelection()
	const node = sel?.rangeCount ? sel.getRangeAt(0).startContainer : null
	const inside = node && root.contains(node) && !closestChip(node)
	if (!inside && root === document.activeElement) caretToEnd()
}

function closestChip(node) {
	const el = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement
	return el?.closest?.('.mention') || null
}

function caretToEnd() {
	const root = editor.value
	if (!root) return
	const range = document.createRange()
	range.selectNodeContents(root)
	range.collapse(false)
	const sel = window.getSelection()
	sel.removeAllRanges()
	sel.addRange(range)
}

// ---- Serialize DOM → HTML komentar ----------------------------------------
const BLOCKS = new Set(['DIV', 'P', 'LI', 'UL', 'OL', 'BLOCKQUOTE', 'PRE'])

function escapeText(text) {
	return text
		.replace(/\ufeff/g, '')
		.replace(/\u00a0/g, ' ')
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
}

function chipHtml(el) {
	const clone = el.cloneNode(true)
	clone.removeAttribute('contenteditable') // span dalam tetap punya, seperti desk
	return clone.outerHTML
}

function isBlank(line) {
	return !line.replace(/<[^>]*>/g, '').replace(/[\s\u00a0\ufeff]/g, '')
}

function serialize() {
	const root = editor.value
	if (!root) return ''
	const lines = []
	let cur = ''
	const flush = () => {
		lines.push(cur)
		cur = ''
	}
	const walk = (parent) => {
		for (const node of parent.childNodes) {
			if (node.nodeType === Node.TEXT_NODE) {
				cur += escapeText(node.data)
			} else if (node.nodeType !== Node.ELEMENT_NODE) {
				continue
			} else if (node.classList.contains('mention')) {
				cur += chipHtml(node)
			} else if (node.tagName === 'BR') {
				flush()
			} else if (BLOCKS.has(node.tagName)) {
				if (cur) flush()
				walk(node)
				if (cur) flush()
			} else {
				walk(node)
			}
		}
	}
	walk(root)
	if (cur) flush()

	// Buang baris kosong di ujung; baris kosong di tengah tetap (jadi <p><br></p>).
	while (lines.length && isBlank(lines[lines.length - 1])) lines.pop()
	while (lines.length && isBlank(lines[0])) lines.shift()
	if (!lines.length) return ''

	const body = lines.map((l) => (isBlank(l) ? '<p><br></p>' : `<p>${l}</p>`)).join('')
	return `<div class="ql-editor read-mode">${body}</div>`
}

function emitValue() {
	const html = serialize()
	hasContent.value = !!html
	lastEmitted = html
	emit('update:modelValue', html)
}

// ---- Event handler ---------------------------------------------------------
function onInput() {
	// Kalau IME sempat merusak chip (preventDefault di beforeinput diabaikan),
	// sisanya dibersihkan di sini lalu caret dikembalikan ke tempat yang bisa
	// diketik.
	if (repairChips()) normalizeEditor()
	emitValue()
	detect()
}

function onKeydown(e) {
	if (open.value) {
		if (e.key === 'ArrowDown') {
			e.preventDefault()
			index.value = (index.value + 1) % items.value.length
			scrollActiveIntoView()
			return
		}
		if (e.key === 'ArrowUp') {
			e.preventDefault()
			index.value = (index.value + items.value.length - 1) % items.value.length
			scrollActiveIntoView()
			return
		}
		if (e.key === 'Enter' || e.key === 'Tab') {
			e.preventDefault()
			pick(index.value)
			return
		}
		if (e.key === 'Escape') {
			e.preventDefault()
			close()
			return
		}
	}
	// Keyboard fisik: hapus chip sebagai satu kesatuan. (Keyboard virtual
	// Android tidak lewat sini — ditangani onBeforeInput.)
	if (e.key === 'Backspace' || e.key === 'Delete') {
		const sel = window.getSelection()
		if (sel?.rangeCount && sel.isCollapsed) {
			const chip = adjacentChip(sel.getRangeAt(0), e.key === 'Backspace')
			if (chip) {
				e.preventDefault()
				removeChip(chip)
			}
		}
		return
	}
	// Ctrl/Cmd+Enter mengirim komentar — sama seperti ControlComment di desk.
	if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
		e.preventDefault()
		emit('submit')
	}
}

function onBlur() {
	// mousedown/touchstart pada daftar sudah di-preventDefault sehingga fokus
	// tidak lepas saat memilih. Penutupan tetap ditunda sedikit: di sebagian
	// webview mobile blur bisa datang lebih dulu dari tap-nya, dan kalau daftar
	// langsung ditutup, pilihan user hilang sebelum sempat terbaca.
	clearTimeout(blurTimer)
	blurTimer = setTimeout(close, 150)
}

function onPaste(e) {
	e.preventDefault()
	const text = e.clipboardData?.getData('text/plain') || ''
	if (!text) return
	const sel = window.getSelection()
	if (!sel || !sel.rangeCount) return
	const range = sel.getRangeAt(0)
	range.deleteContents()
	const lines = text.split(/\r?\n/)
	const frag = document.createDocumentFragment()
	lines.forEach((line, i) => {
		if (i) frag.appendChild(document.createElement('br'))
		frag.appendChild(document.createTextNode(line))
	})
	const last = frag.lastChild
	range.insertNode(frag)
	if (last) {
		const after = document.createRange()
		after.setStartAfter(last)
		after.collapse(true)
		sel.removeAllRanges()
		sel.addRange(after)
	}
	emitValue()
	detect()
}

function scrollActiveIntoView() {
	nextTick(() => {
		list.value?.children?.[index.value]?.scrollIntoView?.({ block: 'nearest' })
	})
}

function close() {
	open.value = false
	items.value = []
	clearTimeout(searchTimer)
	searchSeq++ // batalkan hasil pencarian yang masih di jalan
}

// ---- Posisi daftar ---------------------------------------------------------
// Rect caret dipakai untuk menaruh daftar tepat di bawah kursor. Semua akses
// getBoundingClientRect ditulis defensif: kalau gagal, daftar tetap muncul
// (menempel pada kotak input) — bukan malah ikut tertutup.
function caretRect() {
	const sel = window.getSelection()
	if (sel && sel.rangeCount) {
		const r = sel.getRangeAt(0).getBoundingClientRect?.()
		if (r && (r.width || r.height || r.top)) return r
	}
	return editorRect()
}

function editorRect() {
	return editor.value?.getBoundingClientRect?.() || { top: 0, bottom: 0, left: 0, width: 0 }
}

function position() {
	const anchor = caretRect()
	const box = editorRect()
	// visualViewport: di ponsel tinggi layar berkurang saat keyboard muncul.
	const vh = window.visualViewport?.height || window.innerHeight
	const vw = window.innerWidth
	const width = Math.min(Math.max(box?.width || 240, 220), vw - 16)
	let left = box?.left ?? anchor.left
	if (left + width > vw - 8) left = Math.max(8, vw - width - 8)

	const below = vh - anchor.bottom
	const style = { left: `${left}px`, width: `${width}px` }
	if (below < 200 && anchor.top > below) {
		style.bottom = `${vh - anchor.top + 6}px`
	} else {
		style.top = `${anchor.bottom + 6}px`
	}
	menuStyle.value = style
}

function onReflow() {
	if (open.value) position()
}
window.addEventListener('scroll', onReflow, true)
window.addEventListener('resize', onReflow)
onBeforeUnmount(() => {
	window.removeEventListener('scroll', onReflow, true)
	window.removeEventListener('resize', onReflow)
	clearTimeout(searchTimer)
	clearTimeout(blurTimer)
})

// Sinkron dari parent (reset setelah kirim / batal).
watch(
	() => props.modelValue,
	(val) => {
		if (val === lastEmitted) return
		lastEmitted = val || ''
		if (editor.value) editor.value.innerHTML = val || ''
		hasContent.value = !!(val || '')
	}
)

defineExpose({
	focus: () => editor.value?.focus(),
})
</script>
